detail.command:
set -e
incoming=$(git rev-parse 8aab53119ae674d439b81094e70eb2abcb9d7dcb)
printf '%s\n' "$incoming" > .git/MERGE_HEAD
printf "Merge branch 'cornel/camera-input-and-zoom-5ded69' into cornel/slit-camera-input-and-zoom-100009\n" > .git/MERGE_MSG
cat > src/camera/index.ts <<'EOF'
export * from './CameraCollision';
export * from './CameraInput';
export * from './CameraPose';
export * from './CameraTransition';
export * from './Easing';
export * from './RapierCameraCollision';
export * from './SmoothCameraRig';
export * from './Smoothing';
export * from './ThreeCameraBinding';
EOF
git add -A
echo '--- STATUS ---'
git status --short
echo '--- UNMERGED ---'
git diff --name-only --diff-filter=U
echo '--- MERGE_HEAD ---'
cat .git/MERGE_HEAD
echo '--- INDEX FILE ---'
cat -n src/camera/index.ts
